    identifier: ({ args }) =>
      (args?.['input'] as { mfaToken?: string } | undefined)?.mfaToken || undefined,
  })
  @Public()
  @Mutation(() => AuthPayload, { description: 'Verify MFA during login (TOTP or recovery code)' })
  async verifyMfaLogin(
    @Args('input') input: VerifyMfaLoginInput,
