  value: unknown,
): value is { id: string; channelId: string } {
  return (
    isRecord(value) &&
    typeof value['id'] === 'string' &&
    typeof value['channelId'] === 'string'
  );
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

