// snake_case field names — Rust serde deserialise uyumu için.
// ============================================================================

/**
 * Matches config.rs → LoRaDeviceConfig
 *
 * Her LoRa end-device'ın agent tarafında karşılığı.
 * Edge agent bu yapıyı kullanarak SX1302 concentrator üzerinden
 * cihazla iletişim kurar ve join/uplink işlemlerini yönetir.
 */
interface AgentLoRaDeviceConfig {
  dev_eui: string;
  app_eui: string; // Rust String — null olmaz, varsayılan '0000000000000000'
  app_key: string;
  dev_addr: string | null;
  activation: string; // Rust serde küçük harf: 'otaa' | 'abp'
  device_class: string; // Rust serde küçük harf: 'a' | 'b' | 'c'
  name: string;
  tag_prefix: string;
  codec: string;
  adr_enabled: boolean;
  f_port: number;
}

/**
 * Matches config.rs → LoRaWanConfig
 *
 * Üst seviye LoRaWAN yapılandırması. enabled=true olduğunda
 * agent, SX1302 HAL'ı başlatır ve devices listesindeki cihazları yönetir.
 */
export interface AgentLoRaWanConfig {
  enabled: boolean;
  devices: AgentLoRaDeviceConfig[];
}

/** Top-level I/O config payload sent to the agent via MQTT */
interface AgentIoTagConfig {
  tagName: string;
  protocol: 'gpio' | 'modbus' | 'i2c';
  ioType: string;
  dataType: string;
  rawMin: number | null;
  rawMax: number | null;
  engMin: number | null;
  engMax: number | null;
  engUnit: string | null;
  invert: boolean;
  alarmHH: number | null;
  alarmH: number | null;
  alarmL: number | null;
  alarmLL: number | null;
  deadband: number | null;
  pin?: number;
  slaveId?: number;
  register?: number;
  function?: number;
  registerType?: AgentRegisterType;
  bus?: number;
  address?: number;
  driverType?: string;
  sensorType?: string | null;
}

export interface AgentIoConfig {
  schemaVersion: 2;
  tags: AgentIoTagConfig[];
  lorawan?: AgentLoRaWanConfig;
}

/**
 * Pending ping request for tracking responses
 */
interface PendingPing {
  commandId: string;
  deviceId: string;
  deviceCode: string;
  startTime: number;
  resolve: (result: PingResult) => void;
  reject: (error: Error) => void;
  timeout: NodeJS.Timeout;
}

/**
 * Result of an I/O config push. `success` is true only when the edge device
 * actually acknowledged applying the config (correlated by commandId) —
 * never merely because the command was published (SENSOR-HIGH-064).
 */
export interface IoConfigPushResult {
  success: boolean;
  error?: string;
}

/**
 * Pending `update_io_config` push awaiting the edge device's ack. Resolved by
 * `handleIoConfigAckResponse` when the correlated CommandResponse arrives, or by
 * the timeout. `configHash` is the content hash of the pushed agent config, so
 * the request context can persist the confirmed applied state on success.
 */
interface PendingConfigPush {
  commandId: string;
  deviceId: string;
  deviceCode: string;
  tenantId: string;
  configHash: string;
  startTime: number;
  resolve: (result: IoConfigPushResult) => void;
  timeout: NodeJS.Timeout;
}

/**
 * Outcome of routing an edge response through the I/O-config ack correlation.
 * `matched` is true only when the response resolved a pending push this process
 * was awaiting, so the MQTT listener emits the real-time result event exactly
 * once, on a real ack.
 */
export interface IoConfigAckRouting {
  matched: boolean;
  deviceId?: string;
  tenantId?: string;
  deviceCode?: string;
  success?: boolean;
  error?: string;
}

