import { Logger } from '@nestjs/common';
import { Resolver, Mutation, Args, Query, Context } from '@nestjs/graphql';
import { Request, Response } from 'express';
import { ConfigService } from '@nestjs/config';
import { CurrentUser, Public, SkipTenantGuard } from '@aquaculture/backend-common/decorators';

import { SECURITY_CONSTANTS } from '../../../constants/auth.constants';
import { AuthPayload } from '../dto/auth-response.dto';
import {
  WebAuthnRegistrationChallengeInput,
  WebAuthnRegistrationChallengeResponse,
  WebAuthnRegisterCredentialInput,
  WebAuthnRegisterResponse,
  WebAuthnLoginChallengeInput,
  WebAuthnLoginChallengeResponse,
  WebAuthnVerifyLoginInput,
  WebAuthnCredentialInfo,
  WebAuthnRemoveResponse,
} from '../dto/webauthn.dto';
import { User } from '../entities/user.entity';
import { WebAuthnService } from '../services/webauthn.service';

interface GqlContext {
  req: Request;
  res: Response;
}

@Resolver(() => User)
export class WebAuthnResolver {
  private readonly logger = new Logger(WebAuthnResolver.name);
  private readonly isProduction: boolean;
  private readonly refreshTokenExpiryDays: number;

  constructor(
    private readonly webAuthnService: WebAuthnService,
    private readonly configService: ConfigService,
  ) {
    this.isProduction = this.configService.get<string>('NODE_ENV', 'development') === 'production';
    this.refreshTokenExpiryDays = this.configService.get<number>(
      'REFRESH_TOKEN_EXPIRY_DAYS',
      SECURITY_CONSTANTS.DEFAULT_REFRESH_TOKEN_EXPIRY_DAYS,
    );
  }

  /**
   * Set refresh token as httpOnly cookie (same logic as AuthResolver)
   */
  private setRefreshTokenCookie(res: Response, token: string): void {
    res.cookie('refresh_token', token, {
      httpOnly: true,
      secure: this.isProduction,
      sameSite: 'lax',
      path: '/',
      maxAge: this.refreshTokenExpiryDays * 24 * 60 * 60 * 1000,
    });
  }

  /**
   * Strip refresh token from response body
   */
  private stripRefreshToken(result: AuthPayload): AuthPayload {
    return { ...result, refreshToken: '' };
  }

  // ==========================================================================
  // Registration (Authenticated)
  // ==========================================================================

  /**
   * Generate a challenge for WebAuthn credential registration.
   * User must be authenticated (logged in with email+password first).
   */
  @SkipTenantGuard()
  @Mutation(() => WebAuthnRegistrationChallengeResponse, {
    description: 'Generate challenge for biometric credential registration',
  })
  async webAuthnRegistrationChallenge(
    @CurrentUser('sub') userId: string,
    @Args('input', { nullable: true }) input?: WebAuthnRegistrationChallengeInput,
  ): Promise<WebAuthnRegistrationChallengeResponse> {
    return this.webAuthnService.generateRegistrationChallenge(userId, input?.deviceName);
  }

  /**
   * Register a new WebAuthn credential after the browser ceremony completes.
   * User must be authenticated.
   */
  @SkipTenantGuard()
  @Mutation(() => WebAuthnRegisterResponse, {
    description: 'Register a new biometric credential',
  })
  async registerWebAuthnCredential(
    @CurrentUser('sub') userId: string,
    @Args('input') input: WebAuthnRegisterCredentialInput,
  ): Promise<WebAuthnRegisterResponse> {
    return this.webAuthnService.registerCredential(userId, input);
  }

  /**
   * List all WebAuthn credentials for the current user.
   */
  @SkipTenantGuard()
  @Query(() => [WebAuthnCredentialInfo], {
    description: 'List biometric credentials for the current user',
  })
  async myWebAuthnCredentials(
    @CurrentUser('sub') userId: string,
  ): Promise<WebAuthnCredentialInfo[]> {
    return this.webAuthnService.getUserCredentials(userId);
  }

  /**
   * Check if the current user has any WebAuthn credentials.
   */
  @SkipTenantGuard()
  @Query(() => Boolean, {
    description: 'Check if the current user has biometric login enabled',
  })
  async hasWebAuthnCredentials(
    @CurrentUser('sub') userId: string,
  ): Promise<boolean> {
    return this.webAuthnService.hasCredentials(userId);
  }

  /**
   * Remove a WebAuthn credential.
   */
  @SkipTenantGuard()
  @Mutation(() => WebAuthnRemoveResponse, {
    description: 'Remove a biometric credential',
  })
  async removeWebAuthnCredential(
    @CurrentUser('sub') userId: string,
    @Args('credentialId') credentialId: string,
  ): Promise<WebAuthnRemoveResponse> {
    return this.webAuthnService.removeCredential(userId, credentialId);
  }

  // ==========================================================================
  // Authentication (Public)
  // ==========================================================================

  /**
   * Generate a challenge for WebAuthn login.
   * Public endpoint — called before authentication.
   */
  @Public()
  @Mutation(() => WebAuthnLoginChallengeResponse, {
    description: 'Generate challenge for biometric login',
  })
  async webAuthnLoginChallenge(
    @Args('input') input: WebAuthnLoginChallengeInput,
  ): Promise<WebAuthnLoginChallengeResponse> {
    return this.webAuthnService.generateLoginChallenge(input.email);
  }

  /**
   * Verify WebAuthn assertion and complete biometric login.
   * Public endpoint — issues JWT tokens on success.
   */
  @Public()
  @Mutation(() => AuthPayload, {
    description: 'Verify biometric assertion and login',
  })
  async verifyWebAuthnLogin(
    @Args('input') input: WebAuthnVerifyLoginInput,
    @Context() context: GqlContext,
  ): Promise<AuthPayload> {
    const forwarded = context.req?.headers?.['x-forwarded-for'];
    const ipAddress = context.req?.ip || (Array.isArray(forwarded) ? forwarded[0] : forwarded);
    const userAgent = context.req?.headers?.['user-agent'] as string | undefined;

    const result = await this.webAuthnService.verifyLogin(input, ipAddress, userAgent);

    // Set refresh token as httpOnly cookie
    this.setRefreshTokenCookie(context.res, result.refreshToken);
    return this.stripRefreshToken(result);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';

import { ProposedAction } from './proposed-action.entity';

import { ToolExecutorService } from '../tools/core/tool-executor.service';
import { ToolExecutionContext } from '../tools/core/tool.interface';

/**
 * MOB-HIGH-001 — the human-in-the-loop actuation state machine ("Faz 6").
 *
 * The agent loop persists every held `requiresConfirmation` tool call here via
 * {@link createProposal}; the confirm path (`request.ai.executeAction`, fired
 * by messaging-service's confirmAiAction after its channel-membership check)
 * lands in {@link executeProposal}, which:
 *
 *   1. loads the proposal WITHIN the tenant (cross-tenant ids resolve to
 *      nothing — the lookup itself is tenant-scoped),
 *   2. refuses proposals older than the confirmation window (a stale card
 *      must not actuate equipment/data hours later),
 *   3. claims `proposed → executing` ATOMICALLY (UPDATE … WHERE
 *      status='proposed'), so a double-confirm converges on ONE execution,
 *   4. executes the STORED tool + params — never caller-supplied ones — as
 *      the ORIGINAL requester (their roles are re-checked by the executor)
 *      with `actuationPolicy: 'allowed'`: the human confirmation IS the
 *      authorization override the policy was waiting for,
 *   5. persists the terminal state (completed/failed + result), and the
 *      executor writes the strict actuation audit row (tool_execution_audit).
 */

export interface CreateProposalInput {
  tenantId: string;
  toolName: string;
  params: Record<string, unknown>;
  description: string;
  requestedBy: string;
  requesterRoles: string[];
  persona: string;
  correlationId?: string;
}

export interface ProposalOutcome {
  success: boolean;
  result: string;
}

/** A proposal not confirmed within this window will not actuate. */
const CONFIRMATION_WINDOW_MS = 24 * 60 * 60 * 1000;

@Injectable()
export class ActionProposalService {
  private readonly logger = new Logger(ActionProposalService.name);

  constructor(
    @InjectRepository(ProposedAction)
    private readonly proposalRepo: Repository<ProposedAction>,
    private readonly toolExecutor: ToolExecutorService,
  ) {}

  async createProposal(input: CreateProposalInput): Promise<ProposedAction> {
    const proposal = this.proposalRepo.create({
      tenantId: input.tenantId,
      toolName: input.toolName,
      params: input.params,
      description: input.description,
      requestedBy: input.requestedBy,
      requesterRoles: input.requesterRoles,
      persona: input.persona,
      correlationId: input.correlationId,
      status: 'proposed',
    });
    const saved = await this.proposalRepo.save(proposal);
    this.logger.log(
      `Actuation proposal ${saved.id} created (tool=${input.toolName}, tenant=${input.tenantId})`,
    );
    return saved;
  }

  async executeProposal(
    actionId: string,
    tenantId: string,
    confirmedBy: string,
  ): Promise<ProposalOutcome> {
    // Tenant-scoped lookup: a cross-tenant id resolves to nothing.
    const proposal = await this.proposalRepo.findOne({ where: { id: actionId, tenantId } });
    if (!proposal) {
      this.logger.warn(`executeAction refused: proposal ${actionId} not found for tenant ${tenantId}`);
      return { success: false, result: 'Proposed action not found.' };
    }

    // Idempotent convergence for terminal states.
    if (proposal.status === 'completed') {
      return { success: true, result: proposal.result ?? 'Action already executed.' };
    }
    if (proposal.status === 'failed') {
      return { success: false, result: proposal.result ?? 'Action previously failed.' };
    }
    if (proposal.status === 'executing') {
      return { success: false, result: 'Action is already executing.' };
    }

    // A stale confirmation must not actuate hours later.
    if (Date.now() - proposal.createdAt.getTime() > CONFIRMATION_WINDOW_MS) {
      await this.proposalRepo.update(
        { id: actionId },
        { status: 'failed', result: 'Proposal expired before confirmation.' },
      );
      return { success: false, result: 'Proposed action has expired — ask the AI again.' };
    }

    // Atomic claim: only ONE confirmer transitions proposed → executing.
    const claim = await this.proposalRepo.update(
      { id: actionId, tenantId, status: 'proposed' },
      { status: 'executing', confirmedBy },
    );
    if (!claim.affected) {
      // Lost the race — re-read for the converged outcome.
      const current = await this.proposalRepo.findOne({ where: { id: actionId, tenantId } });
      if (current?.status === 'completed') {
        return { success: true, result: current.result ?? 'Action already executed.' };
      }
      return { success: false, result: 'Action is already being executed.' };
    }

    // Execute the STORED intent as the ORIGINAL requester. The executor
    // re-checks the requester's roles against the tool's requiredPermissions
    // and writes the strict actuation audit row.
    const cleanId = tenantId.replace(/-/g, '').substring(0, 16).toLowerCase();
    const context: ToolExecutionContext = {
      tenantId,
      schemaName: `tenant_${cleanId}`,
      userId: proposal.requestedBy,
      userRoles: proposal.requesterRoles,
      correlationId: proposal.correlationId ?? actionId,
      persona: proposal.persona,
      // The human confirmation IS the authorization override the
      // confirm_required policy was holding for.
      actuationPolicy: 'allowed',
    };

    try {
      const result = await this.toolExecutor.executeTool(proposal.toolName, proposal.params, context);
      const resultText = result.success
        ? `${proposal.description} — done.`
        : `Action failed: ${result.error ?? 'unknown error'}`;
      await this.proposalRepo.update(
        { id: actionId },
        {
          status: result.success ? 'completed' : 'failed',
          result: resultText,
          executedAt: new Date(),
        },
      );
      return { success: result.success, result: resultText };
    } catch (error) {
      const message = error instanceof Error ? error.message : 'unknown error';
      this.logger.error(`executeAction ${actionId} crashed: ${message}`);
      await this.proposalRepo.update(
        { id: actionId },
        { status: 'failed', result: `Action failed: ${message}`, executedAt: new Date() },
      );
      return { success: false, result: `Action failed: ${message}` };
    }
  }
}

/**
 * @module SentimentAnalysisService
 * @description Subscribes to MessageSent events via the outbox consumer pattern
 * and runs sentiment analysis via ai-service NATS request-reply. Stores results
 * in the message_analysis table. Triggers SentimentAlert events when 3+
 * consecutive negative messages are detected from the same sender.
 *
 * Privacy: dual consent (tenant + user) is checked before every analysis.
 * Graceful degradation: ai-service unavailability does not block messaging.
 *
 * @see ADR-012 section 12.2 (Sentiment Analysis Architecture)
 */
import { Injectable, Logger, Inject } from '@nestjs/common';
import { ClientProxy } from '@nestjs/microservices';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, DataSource } from 'typeorm';
import { firstValueFrom, timeout, catchError, of } from 'rxjs';

import { OutboxPublisher } from '@platform/outbox';
import { createBaseEvent, BaseEvent } from '@platform/event-contracts';
import { MessageAnalysis, AnalysisType } from '../entities/message-analysis.entity';
import { AiEgressGateService } from './ai-egress-gate.service';
import type { SentimentResult } from '../entities/message-analysis.entity';

/** NATS request timeout in milliseconds (30 seconds). */
const NATS_TIMEOUT_MS = 30_000;

/** Threshold for negative sentiment (below this triggers alert counting). */
const NEGATIVE_THRESHOLD = 0.3;

/** Number of consecutive negative messages before triggering an alert. */
const CONSECUTIVE_NEGATIVE_ALERT_COUNT = 3;

/** Model version identifier for sentiment analysis results. */
const SENTIMENT_MODEL_VERSION = 'distilbert-sst2-v1.0';

/**
 * Response from ai-service sentiment analysis endpoint.
 */
interface SentimentResponse {
  label: 'POSITIVE' | 'NEGATIVE';
  score: number;
  confidence: number;
}

/**
 * Payload from the MessageSent outbox event.
 */
export interface MessageSentPayload {
  tenantId: string;
  channelId: string;
  messageId: string;
  senderId: string;
  contentType: string;
  createdAt: string;
}

@Injectable()
export class SentimentAnalysisService {
  private readonly logger = new Logger(SentimentAnalysisService.name);

  constructor(
    @InjectRepository(MessageAnalysis)
    private readonly analysisRepo: Repository<MessageAnalysis>,
    private readonly dataSource: DataSource,
    @Inject('NATS_SERVICE')
    private readonly natsClient: ClientProxy,
    private readonly egressGate: AiEgressGateService,
    private readonly outboxPublisher: OutboxPublisher,
  ) {}

  /**
   * Analyze a single message for sentiment. Called by the AnalyzeMessageHandler.
   * Checks privacy gates, calls ai-service, stores result, and checks for alert triggers.
   *
   * @param tenantId - Tenant identifier
   * @param channelId - Channel the message belongs to
   * @param messageId - UUID of the message
   * @param messageCreatedAt - Partition key timestamp
   * @param senderId - User who sent the message
   * @param content - Message text content
   */
  async analyzeMessage(
    tenantId: string,
    channelId: string,
    messageId: string,
    messageCreatedAt: Date,
    senderId: string,
    content: string,
  ): Promise<void> {
    // Privacy gate: route through the single fail-closed AI-egress boundary.
    if (!(await this.egressGate.isAllowed(tenantId, senderId, 'sentiment'))) {
      this.logger.debug(
        `Skipping sentiment analysis for message ${messageId}: AI egress denied`,
      );
      return;
    }

    // Call ai-service via NATS
    const response = await firstValueFrom(
      this.natsClient
        .send<SentimentResponse>('request.ai.analyzeSentiment', { text: content })
        .pipe(
          timeout(NATS_TIMEOUT_MS),
          catchError((err: unknown) => {
            const errMsg = err instanceof Error ? err.message : String(err);
            this.logger.warn(`Sentiment analysis failed for ${messageId}: ${errMsg}`);
            return of(null);
          }),
        ),
    );

    if (!response) {
      return;
    }

    // Store analysis result
    const result: SentimentResult = {
      label: response.label,
      score: response.score,
      confidence: response.confidence,
    };

    const analysis = this.analysisRepo.create({
      messageId,
      messageCreatedAt,
      analysisType: AnalysisType.SENTIMENT,
      result,
      modelVersion: SENTIMENT_MODEL_VERSION,
      analyzedAt: new Date(),
    });

    await this.analysisRepo.save(analysis);

    // Check for consecutive negative sentiment alert trigger
    if (response.score < NEGATIVE_THRESHOLD) {
      await this.checkNegativeTrend(tenantId, channelId, senderId);
    }
  }

  /**
   * Check if the last N messages from a sender in a channel are all negative.
   * If so, publish a SentimentAlert event via NATS.
   */
  private async checkNegativeTrend(
    tenantId: string,
    channelId: string,
    senderId: string,
  ): Promise<void> {
    try {
      // Get last N sentiment analyses for this sender in this channel
      const recentAnalyses: Array<{ score: string }> = await this.dataSource.query(
        `SELECT (ma."result"->>'score')::text as score
         FROM "message_analysis" ma
         INNER JOIN "messages" m ON ma."messageId" = m."id" AND ma."messageCreatedAt" = m."createdAt"
         WHERE m."channelId" = $1
           AND m."senderId" = $2
           AND ma."analysisType" = 'sentiment'
         ORDER BY ma."analyzedAt" DESC
         LIMIT $3`,
        [channelId, senderId, CONSECUTIVE_NEGATIVE_ALERT_COUNT],
      );

      if (recentAnalyses.length < CONSECUTIVE_NEGATIVE_ALERT_COUNT) {
        return;
      }

      const allNegative = recentAnalyses.every(
        (a) => parseFloat(a.score) < NEGATIVE_THRESHOLD,
      );

      if (allNegative) {
        const avgScore =
          recentAnalyses.reduce((sum, a) => sum + parseFloat(a.score), 0) /
          recentAnalyses.length;

        // Store SentimentAlert in the outbox instead of direct NATS emit.
        // BEFORE: this.natsClient.emit(...) — fire-and-forget with no durability guarantee.
        // If NATS was down/restarting at this moment, the alert was silently dropped forever.
        // SentimentAlert consumers (notification-service, hr-service) use this for staff
        // welfare monitoring — a dropped alert could delay intervention.
        // WHY: All other domain events in this service go through the outbox for exactly
        // this reason (guaranteed at-least-once delivery via the outbox worker).
        // Wrapped in dataSource.transaction() because OutboxPublisher.enqueue() requires
        // an active transaction context.
        await this.dataSource.transaction(async (manager) => {
          await this.outboxPublisher.enqueue({
            ...createBaseEvent('SentimentAlert', tenantId),
            channelId,
            userId: senderId,
            avgScore,
            messageCount: CONSECUTIVE_NEGATIVE_ALERT_COUNT,
            detectedAt: new Date().toISOString(),
          },  manager);
        });

        this.logger.warn(
          `SentimentAlert queued via outbox: ${CONSECUTIVE_NEGATIVE_ALERT_COUNT}+ consecutive negative messages ` +
            `from user ${senderId} in channel ${channelId} (avg score: ${avgScore.toFixed(2)})`,
        );
      }
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      this.logger.warn(`Negative trend check failed: ${message}`);
    }
  }
}

